<template><div class="history-page"><PageHeader title="历史记录"><template #actions><el-radio-group v-if="userStore.isSuperuser" v-model="scope" @change="changeScope"><el-radio-button value="personal">我的</el-radio-button><el-radio-button value="global">全局</el-radio-button></el-radio-group><el-button :loading="loading" @click="fetchList">刷新</el-button></template></PageHeader>
  <template v-if="scope==='personal'"><AsyncState v-if="summaryState!=='success'" :state="summaryState" :message="summaryError" empty-text="暂无个人检测摘要" compact @retry="fetchSummary"/><HistorySummary v-else :summary="summary"/></template><el-alert v-else class="scope-note" type="info" :closable="false" show-icon title="当前为管理员全局历史；后端未提供全局 summary，因此不展示当前账号的个人汇总。"/>
  <HistoryFilters v-model:date-range="dateRange" :filters="filters" :scenes="scenes" :type-options="typeOptions" :status-options="statusOptions" :show-user-filter="userStore.isSuperuser&&scope==='global'" @search="search" @reset="reset"/>
  <el-card shadow="never" class="table-card"><el-table :data="items" stripe v-loading="loading" row-key="id"><el-table-column prop="id" label="ID" width="70"/><el-table-column v-if="scope==='global'" label="用户" min-width="130"><template #default="{row}">{{row.username||'-'}}<small> #{{row.user_id}}</small></template></el-table-column><el-table-column label="类型" width="105"><template #default="{row}"><el-tag type="info">{{typeText(row.task_type)}}</el-tag></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><StatusTag group="detection" :status="row.status"/></template></el-table-column><el-table-column prop="scene_name" label="场景" min-width="130"/><el-table-column prop="total_images" label="图片" width="75"/><el-table-column prop="total_objects" label="目标" width="75"/><el-table-column prop="quality_conclusion" label="质检" min-width="110"><template #default="{row}">{{row.quality_conclusion||'-'}}</template></el-table-column><el-table-column label="风险" width="90"><template #default="{row}"><StatusTag v-if="row.risk_level" group="risk" :status="row.risk_level"/><span v-else>-</span></template></el-table-column><el-table-column label="创建时间" min-width="175"><template #default="{row}">{{formatDate(row.created_at)}}</template></el-table-column><el-table-column label="操作" width="250" fixed="right"><template #default="{row}"><ReportActions :row="row" :downloading="reportDownloadingId===row.id" @detail="viewDetail(row)" @report="handleReport(row,$event)" @redetect="handleRedetect(row)" @delete="handleDelete(row)"/></template></el-table-column><template #empty><el-empty :description="errorText||'暂无检测记录'"><el-button v-if="errorText" type="primary" @click="fetchList">重新加载</el-button></el-empty></template></el-table><div class="pagination"><el-pagination v-model:current-page="page.page" v-model:page-size="page.page_size" :page-sizes="[10,20,50]" :total="page.total" layout="total, sizes, prev, pager, next" @size-change="fetchList" @current-change="fetchList"/></div></el-card>
  <DetectionDetailDrawer v-model="drawer" :detail="detail" :loading="detailLoading" :error="detailError" :type-text="typeText" @retry="retryDetail"/>
</div></template>
<script setup>
import { onMounted,reactive,ref } from 'vue';import { ElMessage,ElMessageBox,ElNotification } from 'element-plus';import PageHeader from '@/components/common/PageHeader.vue';import StatusTag from '@/components/common/StatusTag.vue';import HistorySummary from '@/components/history/HistorySummary.vue';import HistoryFilters from '@/components/history/HistoryFilters.vue';import ReportActions from '@/components/history/ReportActions.vue';import DetectionDetailDrawer from '@/components/history/DetectionDetailDrawer.vue';import { deleteTask,downloadReport,downloadReportArchive,getHistorySummary,getScenes,getTaskDetail,getTaskList,redetectTask } from '@/api/history';import { useUserStore } from '@/stores/user'
import { getErrorMessage } from '@/utils/errorMessages'
import AsyncState from '@/components/common/AsyncState.vue'
const userStore=useUserStore(),scope=ref('personal'),items=ref([]),scenes=ref([]),loading=ref(false),errorText=ref(''),summary=ref({total_tasks:0,today_tasks:0,status_counts:{}}),summaryState=ref('loading'),summaryError=ref(''),dateRange=ref([]),drawer=ref(false),detailLoading=ref(false),detailError=ref(''),detailTarget=ref(null),detail=ref({task:null,class_counts:{},results:[]}),reportDownloadingId=ref(null);const filters=reactive({task_type:'',status:'',scene_id:'',defect_class:'',risk_level:'',user_id:undefined});const page=reactive({page:1,page_size:10,total:0})
const typeOptions=[{label:'单图检测',value:'single'},{label:'批量检测',value:'batch'},{label:'文件夹检测',value:'folder'},{label:'ZIP 检测',value:'zip'},{label:'视频检测',value:'video'},{label:'摄像头检测',value:'camera'}];const statusOptions=[{label:'已完成',value:'completed'},{label:'处理中',value:'processing'},{label:'失败',value:'failed'},{label:'等待中',value:'pending'}];const typeText=value=>typeOptions.find(item=>item.value===value)?.label||value||'-';const formatDate=v=>v?new Date(v).toLocaleString('zh-CN'):'-'
async function fetchList(){loading.value=true;errorText.value='';try{const userId=userStore.isSuperuser?(scope.value==='personal'?userStore.user?.id:filters.user_id):undefined;const res=await getTaskList({page:page.page,page_size:page.page_size,task_type:filters.task_type||undefined,status:filters.status||undefined,scene_id:filters.scene_id||undefined,defect_class:filters.defect_class||undefined,risk_level:filters.risk_level||undefined,user_id:userId,start_date:dateRange.value?.[0]||undefined,end_date:dateRange.value?.[1]||undefined});items.value=res.items||[];page.total=res.total||0}catch(error){errorText.value=getErrorMessage(error);items.value=[];page.total=0}finally{loading.value=false}}
async function fetchSummary(){if(scope.value!=='personal')return;summaryState.value='loading';summaryError.value='';try{summary.value=await getHistorySummary();summaryState.value=summary.value?.total_tasks?'success':'empty'}catch(error){summaryState.value='error';summaryError.value=getErrorMessage(error)}}
function search(){page.page=1;fetchList()}function reset(){Object.assign(filters,{task_type:'',status:'',scene_id:'',defect_class:'',risk_level:'',user_id:undefined});dateRange.value=[];page.page=1;fetchList()}function changeScope(){filters.user_id=undefined;page.page=1;fetchList();fetchSummary()}
async function viewDetail(row){detailTarget.value=row;drawer.value=true;detailLoading.value=true;detailError.value='';try{detail.value=await getTaskDetail(row.id)}catch(error){detailError.value=getErrorMessage(error)}finally{detailLoading.value=false}}
function retryDetail(){if(detailTarget.value)viewDetail(detailTarget.value)}
async function handleDelete(row){try{await ElMessageBox.confirm(`确认删除任务 #${row.id}？该操作不可恢复。`,'删除任务',{type:'warning'});await deleteTask(row.id);ElMessage.success('任务已删除');await Promise.all([fetchList(),fetchSummary()])}catch{}}
function saveBlob(blob,filename){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url)}
async function handleReport(row,format){if(reportDownloadingId.value!==null)return ElMessage.info('已有报告正在生成');const archive=format==='archive';reportDownloadingId.value=row.id;const notice=ElNotification({title:archive?'正在生成离线报告':'正在生成检测报告',message:'AIGC Agent 正在整理真实检测结果，首次生成可能需要 1～2 分钟。',type:'info',duration:0});try{const blob=archive?await downloadReportArchive(row.id):await downloadReport(row.id);saveBlob(blob,`detection-report-${row.id}.${archive?'zip':'md'}`);ElMessage.success('报告已下载')}catch{ElNotification.error({title:'报告生成失败',message:'未能完成报告生成，请稍后重试。'})}finally{notice.close();reportDownloadingId.value=null}}
async function handleRedetect(row){try{await ElMessageBox.confirm(`使用任务 #${row.id} 的原始输入重新检测？`,'重新检测',{type:'warning'});const res=await redetectTask(row.id);ElMessage.success(`重检完成${res?.task_id?`，新任务 #${res.task_id}`:''}`);await Promise.all([fetchList(),fetchSummary()])}catch{}}
onMounted(async()=>{try{scenes.value=(await getScenes()).scenes||[]}catch{};await Promise.all([fetchList(),fetchSummary()])})
</script>
<style lang="scss" scoped>.history-page{max-width:$page-max-width;margin:0 auto}.scope-note{margin-bottom:$spacing-md}.table-card{border-radius:$border-radius-lg;border-color:$border-color}.table-card small{color:$text-secondary}.pagination{display:flex;justify-content:flex-end;padding-top:$spacing-md}</style>
